1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] gathered for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row or a name in its source's
5	//! layer. It is pure and total: no I/O, no
6	//! name lists, and its output follows the order of the members it is given.
7	//!
8	//! [`apply`] is its one caller, where a structural answer becomes output (`pipeline::revision`): the [`Inputs`]
9	//! gathered with the answer's resolution (so their reads are its dependencies) and the revision's call-site counts
10	//! (counted again each revision, so an edit to a consumer reaches every component it renders). The checker's merges
11	//! keep the inheritance layers, and so the `used` lists, of the structural answer.
12	
13	pub(crate) mod call_sites;
14	pub(crate) mod forwarding;
15	pub(crate) mod props_type;
16	
17	use std::collections::{BTreeMap, BTreeSet};
18	
19	use crate::types::output::{ComponentEntry, InheritedLayer, PropParent};
20	
21	/// The evidence about one component gathered with its resolution: what its props type writes and what its body does.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub(crate) struct Inputs {
24	    /// The component's place in the project, which its call-site count is looked up by.
25	    pub(crate) site: call_sites::SiteKey,
26	    /// What the props type writes itself.
27	    pub(crate) props_type: props_type::PropsType,
28	    /// What the component's body does with its props; `None` when it has no function of its own.
29	    pub(crate) body: Option<Body>,
30	    /// Whether the listing follows the decision ([`narrow`]): off when every inherited prop is asked for expanded
31	    /// (`collapseInheritedProps: none`, ADR 0028's `relevance: 'all'`); the `used` lists are written either way.
32	    pub(crate) narrows: bool,
33	    /// The sources outside React's types the answer reaches that are ambient by their typings
34	    /// ([`crate::origin::is_ambient_declaration`]): type names by declaring file. Read with the answer's resolution, so
35	    /// an edit to a declaring file refreshes it.
36	    pub(crate) private: BTreeMap<String, BTreeSet<String>>,
37	}
38	
39	/// Decides where each member of `entry`'s props goes, from `inputs`, the revision's `call_sites` of the component and
40	/// the members its listed props and layers reach; keeps the decision on the entry ([`ComponentEntry::relevance`]) and
41	/// lists by it ([`narrow`]).
42	pub(crate) fn apply(entry: &mut ComponentEntry, inputs: &Inputs, call_sites: &CallSites) {
43	    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
44	    let members = props_type::members(&inputs.props_type, rows, &entry.inheritance, &inputs.private);
45	    let shown = decide(&Evidence { members: &members, body: inputs.body.as_ref(), call_sites });
46	    // A row of a member the answer holds only as a name in a collapsed layer (a source the resolver collapsed past its
47	    // thresholds, such as Chakra's `SystemProperties`) has no type to list: it is named in the layer's `used` list
48	    // instead, so a member evidence puts forward is never left unnamed.
49	    let used: BTreeSet<String> = shown
50	        .rows
51	        .iter()
52	        .filter(|name| !entry.props.contains_key(*name) && !entry.notable_inherited.contains_key(*name))
53	        .cloned()
54	        .collect();
55	    // A `Pick` or `Omit` over keys that are not a closed set of literals leaves which members of a source reach
56	    // unproven, so no source is narrowed into a layer that may claim a member that does not reach; React's and the
57	    // DOM's attributes still are, as they are never listed without evidence.
58	    let ambient: BTreeSet<&str> =
59	        members.iter().filter(|member| member.ambient).map(|member| member.name.as_str()).collect();
60	    let declined = inputs.props_type.declined;
61	    // A `Pick` whose key set is not proven selected its members deliberately: none is narrowed, React's included, and
62	    // the checker's merges take every React prop it finds (`Placement::expanded`).
63	    let narrows = inputs.narrows && !inputs.props_type.unproven_pick;
64	    let left = if narrows {
65	        sources(entry, shown.collapsed.iter().filter(|name| !declined || ambient.contains(name.as_str())))
66	    } else {
67	        Vec::new()
68	    };
69	    entry.relevance = Some(std::sync::Arc::new(Placement { left, used, narrows }));
70	    narrow(entry);
71	}
72	
73	/// A source by type name and file, as a prop's `parent` and a layer name it.
74	type Source = (String, String);
75	
76	/// Each of `names` with the source the structural answer gives it, grouped by source: the `parent` of the listed prop,
77	/// and the layer of each collapsed layer holding the name. A name the answer gives no source (a listed prop with no
78	/// `parent`) has no entry: its source is unknown, so no lane narrows it. The project's own sources are held too: a
79	/// generated one (Chakra's `Conditions` in Chakra's own repo) is a layer there as it is when installed.
80	fn sources<'n>(entry: &'n ComponentEntry, names: impl Iterator<Item = &'n String>) -> Vec<(Source, Box<[Box<str>]>)> {
81	    let mut sourced: BTreeMap<(&str, &str), BTreeSet<&str>> = BTreeMap::new();
82	    let mut add = |name: &'n str, type_name: &'n str, file_name: &'n str| {
83	        sourced.entry((type_name, file_name)).or_default().insert(name);
84	    };
85	    let names: BTreeSet<&'n str> = names.map(String::as_str).collect();
86	    for name in &names {
87	        let listed = entry.props.get(*name).or_else(|| entry.notable_inherited.get(*name));
88	        if let Some(parent) = listed.and_then(|prop| prop.parent.as_ref()) {
89	            add(name, &parent.name, &parent.file_name);
90	        }
91	    }
92	    // Each layer's members are walked once against the set of names, never the layer once per name: a layer of
93	    // thousands of members with every member left out is linear, not quadratic.
94	    for layer in &entry.inheritance {
95	        for name in wanted_members(layer, |name| names.contains(name)) {
96	            add(name, &layer.type_name, &layer.file_name);
97	        }
98	    }
99	    sourced
100	        .into_iter()
101	        .map(|((type_name, file_name), names)| {
102	            ((type_name.to_owned(), file_name.to_owned()), names.into_iter().map(Box::from).collect())
103	        })
104	        .collect()
105	}
106	
107	/// The members of `layer` that `wanted` takes, in the layer's order, each member asked once.
108	fn wanted_members(layer: &InheritedLayer, mut wanted: impl FnMut(&str) -> bool) -> impl Iterator<Item = &str> {
109	    layer.members.iter().map(String::as_str).filter(move |name| wanted(name))
110	}
111	
112	/// What [`decide`] said of one component, kept on its entry so that every merge of the checker's props into it lists by
113	/// the same decision ([`narrow`]): the decision is made once, from the structural answer's evidence.
114	#[derive(Debug, Clone, Default, PartialEq, Eq)]
115	pub struct Placement {
116	    /// The members evidence leaves out of the listing ([`Shown::collapsed`]), by name under the
117	    /// source the structural answer gives each, sources in order and each source's names sorted: a listed prop is left
118	    /// out only when both match, so a prop of another source with the same name, or one the structural answer gave no
119	    /// source, is never hidden by it. Each source's type name and path is held once per component, not once per name.
120	    left: Vec<(Source, Box<[Box<str>]>)>,
121	    /// The rows [`decide`] puts forward that the structural answer holds only as names in a collapsed layer: named in
122	    /// that layer's `used` list.
123	    used: BTreeSet<String>,
124	    /// Whether the listing follows the decision ([`Inputs::narrows`]); off in the expanded view and for a `Pick` whose
125	    /// keys are not proven.
126	    narrows: bool,
127	}
128	
129	impl Placement {
130	    /// Whether the answer lists every resolved prop: the expanded view (`collapseInheritedProps: none`), or a `Pick`
131	    /// whose keys are not proven (what it selects is deliberate). A checker merge then takes every `@types/react` prop
132	    /// the checker finds.
133	    pub(crate) fn expanded(&self) -> bool {
134	        !self.narrows
135	    }
136	
137	    /// Whether the decision leaves `name`, declared by `parent`, out of the listing.
138	    fn leaves(&self, name: &str, parent: &PropParent) -> bool {
139	        let source = (parent.name.as_str(), parent.file_name.as_str());
140	        self.left
141	            .binary_search_by(|((type_name, file_name), _)| (type_name.as_str(), file_name.as_str()).cmp(&source))
142	            .ok()
143	            .and_then(|at| self.left.get(at))
144	            .is_some_and(|(_, names)| names.binary_search_by(|held| (**held).cmp(name)).is_ok())
145	    }
146	}
147	
148	/// Lists `entry` by its kept [`Placement`]: a listed prop (in `props` or `notableInherited`) the decision leaves out
149	/// moves to the layer of its source, as a name, when the placement left out that name from that same source, whoever
150	/// declares it: [`decide`] leaves out only ambient or generated members. Its home is the layer of its `parent` (by
151	/// type name and file), else, for a source of React's, the entry's HTML element layer, else a new layer of its
152	/// `parent` (a library's private source keeps its own layer). A prop with no `parent` has no known source and stays
153	/// listed: no name is ever lost. Then each layer's `used` list is written. Without a placement nothing changes. Run by
154	/// [`apply`] and at the end of each merge of the checker's props, which may list again what the structural answer
155	/// left out.
156	pub(crate) fn narrow(entry: &mut ComponentEntry) {
157	    let Some(placement) = entry.relevance.clone() else { return };
158	    let ComponentEntry { props, notable_inherited, inheritance, .. } = entry;
159	    // The names the layers hold, read once and only when a prop is left out: it joins a layer only when none holds
160	    // its name yet.
161	    let mut layered: Option<BTreeSet<String>> = None;
162	    for listing in [props, notable_inherited] {
163	        listing.retain(|name, prop| {
164	            let Some(parent) = prop.parent.as_ref() else { return true };
165	            if !placement.leaves(name, parent) {
166	                return true;
167	            }
168	            // Each name is held once: a layer already holding it keeps it (`listed_props_leave_layers`' rule).
169	            let held = layered
170	                .get_or_insert_with(|| inheritance.iter().flat_map(|layer| layer.members.iter().cloned()).collect());
171	            if held.insert(name.clone()) {
172	                home(inheritance, parent).members.push(name.clone());
173	            }
174	            false
175	        });
176	    }
177	    for layer in inheritance.iter_mut() {
178	        layer.total_props = layer.total_props.max(u32::try_from(layer.members.len()).unwrap_or(u32::MAX));
179	        layer.used = layer.members.iter().filter(|name| placement.used.contains(*name)).cloned().collect();
180	    }
181	}
182	
183	/// The layer a prop declared in `parent` is left in ([`narrow`]): made when the entry has none.
184	fn home<'l>(layers: &'l mut Vec<InheritedLayer>, parent: &PropParent) -> &'l mut InheritedLayer {
185	    let ambient = crate::origin::declaration_origin(&parent.file_name).is_ambient();
186	    let at = layers
187	        .iter()
188	        .position(|layer| layer.type_name == parent.name && layer.file_name == parent.file_name)
189	        .or_else(|| {
190	            ambient
191	                .then(|| {
192	                    layers.iter().position(|layer| {
193	                        layer.html_element.is_some() && crate::origin::declaration_origin(&layer.file_name).is_ambient()
194	                    })
195	                })
196	                .flatten()
197	        });
198	    let at = at.unwrap_or_else(|| {
199	        layers.push(InheritedLayer {
200	            type_name: parent.name.clone(),
201	            file_name: parent.file_name.clone(),
202	            omitted: Vec::new(),
203	            html_element: None,
204	            total_props: 0,
205	            members: Vec::new(),
206	            used: Vec::new(),
207	        });
208	        layers.len() - 1
209	    });
210	    &mut layers[at]
211	}
