213	/// Everything known about the members one component's props type reaches.
214	#[derive(Debug, Clone, Copy)]
215	pub(crate) struct Evidence<'a> {
216	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
217	    /// once, by its first member.
218	    pub(crate) members: &'a [Member],
219	    /// What the component's own function body does with its props; `None` when it has no function of its own.
220	    pub(crate) body: Option<&'a Body>,
221	    /// The props passed at the component's JSX call sites across the project.
222	    pub(crate) call_sites: &'a CallSites,
223	}
224	
225	/// One member the props type reaches, with the signals its declaration gives.
226	#[derive(Debug, Clone, Default, PartialEq, Eq)]
227	pub(crate) struct Member {
228	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
229	    pub(crate) name: String,
230	    /// The props type declares it itself, not through an inherited source.
231	    pub(crate) own: bool,
232	    /// A key a `Pick<X, …>` names.
233	    pub(crate) picked: bool,
234	    /// It redeclares or narrows a base member.
235	    pub(crate) overrides: bool,
236	    /// It is not optional.
237	    pub(crate) required: bool,
238	    /// Its declaration carries a `@default` tag.
239	    pub(crate) default_tag: bool,
240	    /// It carries a JSDoc comment: orders the rows, never shows a member.
241	    pub(crate) documented: bool,
242	    /// Its type is a union of literals: orders the rows, never shows a member.
243	    pub(crate) literal_union: bool,
244	    /// Every declaration of it is ambient ([`crate::origin::is_ambient_declaration`]): React's own, or one its library
245	    /// marks private. A member a library's API declares too, or with no known declaration, is not. Never decided by the
246	    /// name.
247	    pub(crate) ambient: bool,
248	    /// One of a generated set, not an API: a member of a source the resolver collapsed, of a source reaching with more
249	    /// than [`LARGE_API_SOURCE`](crate::types::options::LARGE_API_SOURCE) members, or one a mapped type copies from the
250	    /// keys of an interface of more than [`COLLAPSE_THRESHOLD`](crate::types::options::COLLAPSE_THRESHOLD) members.
251	    /// Decided by structure and size, never by a name.
252	    pub(crate) large: bool,
253	}
254	
255	/// What a component's function body does with its props, read from the syntax alone.
256	#[derive(Debug, Clone, Default, PartialEq, Eq)]
257	pub(crate) struct Body {
258	    /// The props the body reads, destructures (with or without a default) or passes by name. What the body says is
259	    /// certain; its silence is not read: a member it never names keeps the place the props type gives it.
260	    pub(crate) reads: Vec<String>,
261	    /// The JSX elements the body writes, in source order.
262	    pub(crate) elements: Vec<Element>,
263	}
264	
265	/// One JSX element a component body writes.
266	#[derive(Debug, Clone, PartialEq, Eq)]
267	pub(crate) struct Element {
268	    /// What the tag resolves to.
269	    pub(crate) target: Target,
270	    /// Its attributes in source order, so a named attribute's place before or after a spread is kept.
271	    pub(crate) attributes: Vec<Attribute>,
272	}
273	
274	/// What a JSX tag resolves to.
275	#[derive(Debug, Clone, PartialEq, Eq)]
276	pub(crate) enum Target {
277	    /// A host element: a spread onto it passes only ambient DOM attributes.
278	    Dom,
279	    /// A component resolved by symbol and import, with the names of its own non-ambient props.
280	    Component(Vec<String>),
281	    /// A component tag that did not resolve: a spread onto it forwards nothing known.
282	    Unresolved,
283	}
284	
285	/// One attribute of a JSX element.
286	#[derive(Debug, Clone, PartialEq, Eq)]
287	pub(crate) enum Attribute {
288	    /// `name={value}`: set after a spread, it fixes `name`; its value adds nothing.
289	    Named(String),
290	    /// `{...value}`.
291	    Spread(SpreadOf),
292	}
293	
294	/// What a JSX spread attribute spreads.
295	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
296	pub(crate) enum SpreadOf {
297	    /// The props object, whole.
298	    Props,
299	    /// A rest binding of the props object.
300	    Rest,
301	    /// Any other expression: no evidence about the props.
302	    Other,
303	}
304	
305	/// How often each prop is passed at a component's JSX call sites.
306	#[derive(Debug, Clone, Default, PartialEq, Eq)]
307	pub(crate) struct CallSites {
308	    /// The number of call sites.
309	    pub(crate) sites: u32,
310	    /// Each prop passed at them, with the number of sites passing it.
311	    pub(crate) passed: Vec<(String, u32)>,
312	}
313	
314	/// No call sites: no evidence.
315	pub(crate) static NO_CALL_SITES: CallSites = CallSites { sites: 0, passed: Vec::new() };
316	
317	impl CallSites {
318	    /// Whether `count` of the sites reach the floor of `max(2, 20%)` of them.
319	    fn at_floor(&self, count: u32) -> bool {
320	        count >= 2 && u64::from(count) * 5 >= u64::from(self.sites)
321	    }
322	}
323	
324	/// Where [`decide`] puts each member, both lists in the order of [`Evidence::members`], except that `rows` puts the
325	/// documented and literal-union members first.
326	#[derive(Debug, Clone, Default, PartialEq, Eq)]
327	pub(crate) struct Shown {
328	    /// Typed rows.
329	    pub(crate) rows: Vec<String>,
330	    /// Members left as names in their source's layer.
331	    pub(crate) collapsed: Vec<String>,
332	}
333	
334	/// Decides, from the evidence alone, where each member of a component's props goes (ADR 0028, A2):
335	///
336	/// 1. The main props are listed in full: every member the props type declares itself (own, picked, overriding,
337	///    required or defaulted), and every member of a source that is neither ambient nor large ([`Member::large`]), with
338	///    no story or call site needed.
339	/// 2. What the component uses directly is listed from any source: a member its body reads, destructures or passes by
340	///    name, or that a spread forwards to a resolved component's own props. A spread onto a DOM tag is no evidence, and
341	///    a body that hands its props on where the syntax cannot follow promotes nothing and hides nothing.
342	/// 3. Every other member of an ambient or large source stays a name in its layer, unless
343	/// 4. it is passed at the call-site floor (`max(2, 20%)` of the component's call sites).
344	pub(crate) fn decide(evidence: &Evidence<'_>) -> Shown {
345	    let body = evidence.body;
346	    let reads: BTreeSet<&str> = body.map(|body| body.reads.iter().map(String::as_str).collect()).unwrap_or_default();
347	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
348	    let at_floor: BTreeSet<&str> = evidence
349	        .call_sites
350	        .passed
351	        .iter()
352	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
353	        .map(|(name, _)| name.as_str())
354	        .collect();
355	    let mut shown = Shown::default();
356	    let mut ordered_rows = Vec::new();
357	    let mut placed = BTreeSet::new();
358	    for member in evidence.members {
359	        let name = member.name.as_str();
360	        if !placed.insert(name) {
361	            continue;
362	        }
363	        let declared = member.own || member.picked || member.overrides || member.required || member.default_tag;
364	        let api = !(member.ambient || member.large);
365	        let used = reads.contains(name) || forwarded.contains(name);
366	        if declared || api || used || at_floor.contains(name) {
367	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
368	        } else {
369	            shown.collapsed.push(member.name.clone());
370	        }
371	    }
372	    ordered_rows.sort_by_key(|(plain, _)| *plain);
373	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
374	    shown
375	}
376	
377	impl Body {
378	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
379	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
380	    fn forwarded(&self) -> BTreeSet<&str> {
381	        let mut forwarded = BTreeSet::new();
382	        for element in &self.elements {
383	            let Target::Component(own) = &element.target else { continue };
384	            for (at, attribute) in element.attributes.iter().enumerate() {
385	                if !attribute.spreads_props() {
386	                    continue;
387	                }
388	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
389	                    .iter()
390	                    .filter_map(|after| match after {
391	                        Attribute::Named(name) => Some(name.as_str()),
392	                        Attribute::Spread(_) => None,
393	                    })
394	                    .collect();
395	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
396	            }
397	        }
398	        forwarded
399	    }
400	}
401	
402	impl Attribute {
403	    /// Whether the attribute spreads the props object or a rest binding of it.
404	    fn spreads_props(&self) -> bool {
405	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
406	    }
407	}
