409	#[cfg(test)]
410	mod tests {
411	    use super::*;
412	
413	    /// Where a member went, for the tables.
414	    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
415	    enum Placed {
416	        Row,
417	        Collapsed,
418	    }
419	
420	    /// A member of a large source (a style system's, say): listed only on evidence.
421	    fn inherited(name: &str) -> Member {
422	        Member { name: name.to_owned(), large: true, ..Member::default() }
423	    }
424	
425	    /// A member of an API source: neither ambient nor large.
426	    fn api(name: &str) -> Member {
427	        Member { name: name.to_owned(), ..Member::default() }
428	    }
429	
430	    fn ambient(name: &str) -> Member {
431	        Member { ambient: true, ..inherited(name) }
432	    }
433	
434	    fn strings(names: &[&str]) -> Vec<String> {
435	        names.iter().map(|name| (*name).to_owned()).collect()
436	    }
437	
438	    fn reading(names: &[&str]) -> Body {
439	        Body { reads: strings(names), ..Body::default() }
440	    }
441	
442	    fn layer(type_name: &str, file_name: &str, members: Vec<String>) -> InheritedLayer {
443	        InheritedLayer {
444	            type_name: type_name.to_owned(),
445	            file_name: file_name.to_owned(),
446	            omitted: Vec::new(),
447	            html_element: None,
448	            total_props: u32::try_from(members.len()).unwrap(),
449	            members,
450	            used: Vec::new(),
451	        }
452	    }
453	
454	    #[test]
455	    fn a_layer_is_walked_once_whatever_number_of_names_it_leaves_out() {
456	        // Entire finding on change 288: a layer of 4,000 members with every member left out was rescanned once per
457	        // name (16 million comparisons). Each member is asked once.
458	        let members: Vec<String> = (0..4_000).map(|i| format!("m{i}")).collect();
459	        let big = layer("Big", "/p/node_modules/lib/big.d.ts", members.clone());
460	        let mut asked = 0;
461	        let wanted: BTreeSet<&str> = members.iter().map(String::as_str).collect();
462	        let found = wanted_members(&big, |name| {
463	            asked += 1;
464	            wanted.contains(name)
465	        })
466	        .count();
467	        assert_eq!((found, asked), (4_000, 4_000));
468	        let entry = ComponentEntry { inheritance: vec![big], ..button(vec![]) };
469	        let left = sources(&entry, members.iter());
470	        assert_eq!(left.len(), 1);
471	        assert_eq!(left[0].1.len(), 4_000);
472	    }
473	
474	    #[test]
475	    fn a_project_source_is_narrowed_like_a_dependency_s() {
476	        // The generated rule holds in the project too (Chakra's own repo): a project source's left-out names are held.
477	        let entry = ComponentEntry {
478	            inheritance: vec![layer("Conditions", "/p/src/conditions.ts", strings(&["_hover", "_active"]))],
479	            ..button(vec![])
480	        };
481	        let left = sources(&entry, strings(&["_hover"]).iter());
