/// Whether `mapping` re-binds a component the project itself declares under the same name: `const Alert =
/// InternalAlert` where `InternalAlert` is the project's `Alert`, or `const { Option } = Select` where `Select` is a
/// project component and a project component `Option` exists. An alias of a package's component is not one of these.
fn aliases_project_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> bool {
    if mapping.rule != DetectionRule::ImportedMemberAlias {
        return false;
    }
    let Some(CollectedType::TypeOf(target)) = mapping.props_type_args.first() else { return false };
    let mut ignored = Vec::new();
    let mut project = |name: &str| {
        let (file, canonical) = import::resolve_to_canonical(name, &mapping.file_path, ctx, &mut ignored)?;
        ctx.component_mapping(&file, &canonical).map(|found| found.component_name.clone())
    };
    match target.split_once('.') {
        None => project(target).is_some_and(|declared| declared == mapping.component_name),
        Some((base, _)) => {
            project(base).is_some()
                && ctx.global.component_mappings.iter().any(|other| {
                    other.rule != DetectionRule::ImportedMemberAlias && other.component_name == mapping.component_name
                })
        }
    }
}

/// `resolve_component`, with the diagnostics of replayed interface chains shared rather than copied.
pub(crate) fn resolve_component_shared(
    mapping: &ComponentMapping,
    ctx: &ResolutionContext,
) -> (ComponentEntry, ResolvedDiagnostics) {
    // The component the project already declares under this name, not a second one: nothing to document here, so
    // the entry is left empty and goes unpublished like an alias whose package isn't loaded.
    if aliases_project_component(mapping, ctx) {
        return (unpublished_entry(mapping), ResolvedDiagnostics { own: Vec::new(), shared: Vec::new() });
    }
    let mut state = ResolveState { scope: TypeScope::new(mapping.type_params.iter()), ..ResolveState::default() };

    // A component a generic call builds has the props its callee's result type declares; the props type the extractor
    // selected is for a callee whose result isn't known.
    // The factory's own props resolve beside the main chain, not inside it: a type both reach is shared, not a cycle.
    // The render function's own type parameters are in scope for these props only, not for the callee's result.
    let mut factory_state = mapping.factory_props.as_ref().map(|_| {
        let mut branch = state.branch();
        branch.scope = TypeScope::new(mapping.type_params.iter().chain(&mapping.factory_type_params));
        branch
    });
    let result = callee::result_chain(mapping, ctx, &mut state);
    // A call to a function whose result is no component is no component: nothing to document, nothing to report.
    if result.is_none() && mapping.rule == DetectionRule::FactoryResult {
        return (unpublished_entry(mapping), ResolvedDiagnostics { own: Vec::new(), shared: Vec::new() });
    }
    let mut chain = result.unwrap_or_else(|| {
        chain::resolve_props_chain(
            mapping.props_type_name.as_str(),
            &mapping.props_type_args,
            &mapping.file_path,
            mapping,
            ctx,
            &mut state,
            0,
        )
    });
    // The props a factory call's own arguments give the component, which the props type read above can lack: the
    // variant keys of its style recipe, or the annotated props of its render function (`extractor::factory_props`).
    if let (Some(own), Some(mut branch)) = (&mapping.factory_props, factory_state.take()) {
        // A named props type is the root of the callback's props, as a function component's is: depth 0, so a large
        // interface of its own is not collapsed (its inherited sources still can).
        let own = match own {
            CollectedType::Named { name, args } => {
                chain::resolve_props_chain(name.as_str(), args, &mapping.file_path, mapping, ctx, &mut branch, 0)
            }
            _ => alias::resolve_base_as_chain(own, &mapping.file_path, mapping, ctx, &mut branch, 0),
        };
        state.absorb(branch);
        chain.add_absent(own);
    }

    // Build props BTreeMap — own props win over inherited props with same name.
    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
    for prop in chain.props {
        props.entry(prop.name.clone()).or_insert(prop);
    }
    apply_param_defaults(mapping, &mut props, ctx);

    // Populate notable_inherited from HTML element layers and non-HTML inherited layers. Curated mode lists the
    // curated attributes there; Full mode lists all of them in `props`, except for a layer whose attributes the
    // interface chain already merged (`total_props`); None mode lists none.
    let mut notable_inherited: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
    for layer in &chain.inheritance {
        if layer.html_element.is_none() {
            continue;
        }
        match ctx.html_attributes {
            crate::types::options::HtmlAttributeMode::None => {}
            crate::types::options::HtmlAttributeMode::Full => {
                if layer.total_props == 0 {
                    let added =
                        html::layer_attributes(layer, true, |name| props.contains_key(name), ctx, &mut state, 0);
                    for prop in added {
                        props.entry(prop.name.clone()).or_insert(prop);
                    }
                }
            }
            crate::types::options::HtmlAttributeMode::Curated => {
                let added = html::layer_attributes(
                    layer,
                    false,
                    |name| props.contains_key(name) || notable_inherited.contains_key(name),
                    ctx,
                    &mut state,
                    0,
                );
                for prop in added {
                    notable_inherited.entry(prop.name.clone()).or_insert(prop);
                }
            }
        }
    }
    // A `forwardRef` component takes `ref` whatever its props type declares. The element type isn't recorded, so it is
    // `Ref<unknown>` unless the props or an HTML layer gave the real declaration.
    let takes_ref = matches!(mapping.rule, DetectionRule::ForwardRef | DetectionRule::ForwardRefExoticDecl);
    if takes_ref && ctx.html_attributes != crate::types::options::HtmlAttributeMode::None {
        let target = if ctx.html_attributes == crate::types::options::HtmlAttributeMode::Full {
            &mut props
        } else {
            &mut notable_inherited
        };
        if !target.contains_key("ref") {
            let ref_type = PropType::Named {
                name: "Ref".into(),
                args: vec![PropType::Named { name: "unknown".into(), args: vec![] }],
            };
            // The component takes it, so no interface is its parent, and a consumer that hides React's inherited props
            // (the addon's `collapseInheritedProps`) still shows it.
            let parent = None;
            target.insert(
                "ref".to_owned(),
                ctx.share(ParsedProp::new(
                    "ref".to_owned(),
                    ref_type,
                    false,
                    None,
                    String::new(),
                    Default::default(),
                    parent,
                    vec![],
                )),
            );
        }
    }
    // A collapsed source's notable props (collapse); the only non-HTML layers. Each is the component's prop as one it
    // lists is, so a destructuring default reaches it too (`Box({ className = "base" }: BoxProps)`).
    let mut collapsed_notable: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
    for prop in &chain.notable {
        if !props.contains_key(&prop.name) && !notable_inherited.contains_key(&prop.name) {
            collapsed_notable.entry(prop.name.clone()).or_insert_with(|| prop.clone());
        }
    }
    apply_param_defaults(mapping, &mut collapsed_notable, ctx);
    notable_inherited.extend(collapsed_notable);

    // Detect discriminated union if applicable.
    let discriminant_prop = chain.discriminant_prop;

    let mut entry = ComponentEntry {
        relevance: None,
        display_name: mapping.component_name.clone(),
        file_path: mapping.file_path.clone(),
        description: mapping.description.clone(),
        props,
        inheritance: one_layer_per_collapsed_source(chain.inheritance),
        notable_inherited,
        discriminant_prop,
        composes: chain.composes,
        tags: mapping.tags.clone(),
        methods: vec![],
        detected_by: mapping.rule,
        exported: mapping.exported(),
        exports: mapping.exports.clone(),
    };
    crate::types::semantic::listed_props_leave_layers(&mut entry, false);
    (entry, ResolvedDiagnostics { own: state.diagnostics, shared: state.shared_diagnostics })
}

