26	/// Record that this resolution reads React's augmentations: every file that declares into the `React` namespace, and
27	/// that the set of such files matters. Called wherever augmentations are read, and on the path that reuses a cached
28	/// attribute list, so every component that depends on them records it.
29	fn note_augmentations(react_file: &Utf8Path, ctx: &ResolutionContext) {
30	    use std::borrow::Borrow;
