36	/// (`NamedTypeIndex::react_augmentations`): the project's and the loaded dependencies' in every mode, since curated mode
37	/// indexes only React's own file apart.
38	fn merged_interfaces<'a>(key: &str, react_file: &Utf8Path, ctx: &'a ResolutionContext) -> Vec<&'a CollectedInterface> {
39	    note_augmentations(react_file, ctx);
40	    let mut layers: Vec<&CollectedInterface> =
41	        ctx.react_index().lookup_interface_exact(react_file, key).into_iter().collect();
42	    layers.extend(ctx.named_types.react_augmentations(react_file, key));
43	    layers
44	}
