59	    element: &str,
60	    name: &str,
61	    react_file: &Utf8Path,
62	    ctx: &ResolutionContext,
63	    state: &mut ResolveState,
64	    depth: u8,
65	) -> Option<ParsedProp> {
66	    attribute_from(intrinsic_element(element, react_file, ctx)?.clone(), name, react_file, ctx, state, depth)
67	}
68	
69	/// The declaration of attribute `name` among the members `root` (a type of React's) names, found through the interfaces
70	/// and aliases it extends and intersects.
71	fn attribute_from(
72	    root: CollectedType,
73	    name: &str,
74	    react_file: &Utf8Path,
75	    ctx: &ResolutionContext,
76	    state: &mut ResolveState,
77	    depth: u8,
78	) -> Option<ParsedProp> {
79	    // Declared inside `declare namespace React`, so keyed by their qualified names whichever way they are referenced.
80	    let key = |type_name: &str| format!("React.{}", type_name.strip_prefix("React.").unwrap_or(type_name));
81	    let mut pending = VecDeque::from([root]);
82	    // React's attribute types are a small tree; the bound only guards against a malformed declaration file.
83	    for _ in 0..64 {
84	        match pending.pop_front()? {
85	            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
86	            CollectedType::Intersection(members) => pending.extend(members),
87	            CollectedType::Named { name: type_name, args } => {
88	                let key = key(&type_name);
89	                // Defaulted parameters (`T = Element`) are not supplied, and need no warning.
90	                let mut ignored = Vec::new();
91	                let layers = merged_interfaces(&key, react_file, ctx);
92	                if !layers.is_empty() {
93	                    for iface in layers {
94	                        let params = index_of(iface, react_file, ctx).lookup_interface_type_params_for(iface);
95	                        let subst = params.map(|params| build_substitution(params, &args, react_file, &mut ignored));
96	                        let substituted =
97	                            |ty: &CollectedType| subst.as_ref().map_or_else(|| ty.clone(), |s| substitute_type(ty, s));
98	                        if let Some(raw) = iface.props.iter().find(|prop| prop.name == name) {
99	                            let ty = substituted(&raw.collected_type);
100	                            let prop_type = resolve_collected_type(&ty, &iface.file_path, ctx, state, depth);
101	                            let parent =
102	                                PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() };
103	                            return Some(ParsedProp::new(
104	                                name.to_owned(),
105	                                prop_type,
106	                                raw.required,
107	                                None,
108	                                raw.description.clone(),
109	                                raw.tags.clone(),
110	                                Some(parent.clone()),
111	                                vec![parent],
112	                            ));
113	                        }
114	                        pending.extend(iface.extends.iter().map(|extends| {
115	                            let (ExtendsRef::SameFile { name, type_args }
116	                            | ExtendsRef::Imported { local_name: name, type_args, .. }
117	                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
118	                            CollectedType::Named {
119	                                name: name.clone(),
120	                                args: type_args.iter().map(substituted).collect(),
121	                            }
122	                        }));
123	                    }
124	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
125	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
126	                        Some(params) => {
127	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut ignored))
128	                        }
129	                        None => alias.clone(),
130	                    };
131	                    match alias {
132	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
133	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
134	                        // None of these names an attribute by itself; a new variant must say whether it does.
135	                        CollectedTypeAlias::Omit { .. }
136	                        | CollectedTypeAlias::Pick { .. }
137	                        | CollectedTypeAlias::Partial { .. }
138	                        | CollectedTypeAlias::Required { .. }
139	                        | CollectedTypeAlias::Union { .. }
140	                        | CollectedTypeAlias::LiteralUnion { .. } => {}
141	                    }
142	                }
143	            }
144	            _ => {}
145	        }
146	    }
147	    None
148	}
149	
150	/// Every attribute name `JSX.IntrinsicElements[element]` declares in React's own types at `react_file`, in the order
151	/// `react_attribute` reads them; empty without those types.
152	fn react_attribute_names(element: &str, react_file: &Utf8Path, ctx: &ResolutionContext) -> Vec<String> {
153	    match intrinsic_element(element, react_file, ctx) {
154	        Some(root) => attribute_names_from(root.clone(), react_file, ctx),
155	        None => Vec::new(),
156	    }
157	}
158	
159	/// Every attribute name `root` (a type of React's) carries, in the order `attribute_from` reads them.
160	fn attribute_names_from(root: CollectedType, react_file: &Utf8Path, ctx: &ResolutionContext) -> Vec<String> {
161	    let mut names: Vec<String> = Vec::new();
162	    let mut pending = VecDeque::from([root]);
163	    for _ in 0..64 {
164	        let Some(next) = pending.pop_front() else {
165	            break;
166	        };
167	        match next {
168	            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
169	            CollectedType::Intersection(members) => pending.extend(members),
170	            CollectedType::Named { name: type_name, args } => {
171	                let key = format!("React.{}", type_name.strip_prefix("React.").unwrap_or(&type_name));
172	                let layers = merged_interfaces(&key, react_file, ctx);
173	                if !layers.is_empty() {
174	                    for iface in layers {
175	                        names.extend(iface.props.iter().map(|prop| prop.name.clone()));
176	                        pending.extend(iface.extends.iter().map(|extends| {
177	                            let (ExtendsRef::SameFile { name, type_args }
178	                            | ExtendsRef::Imported { local_name: name, type_args, .. }
179	                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
180	                            CollectedType::Named { name: name.clone(), args: type_args.clone() }
181	                        }));
182	                    }
183	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
184	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
185	                        Some(params) => {
186	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut Vec::new()))
187	                        }
188	                        None => alias.clone(),
189	                    };
190	                    match alias {
191	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
192	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
193	                        // None of these names an attribute by itself; a new variant must say whether it does.
194	                        CollectedTypeAlias::Omit { .. }
195	                        | CollectedTypeAlias::Pick { .. }
196	                        | CollectedTypeAlias::Partial { .. }
197	                        | CollectedTypeAlias::Required { .. }
198	                        | CollectedTypeAlias::Union { .. }
199	                        | CollectedTypeAlias::LiteralUnion { .. } => {}
200	                    }
201	                }
202	            }
203	            _ => {}
204	        }
205	    }
206	    let mut seen = rustc_hash::FxHashSet::default();
207	    names.retain(|name| seen.insert(name.clone()));
208	    names
209	}
210	
211	/// The attributes of an HTML layer's element that `has` doesn't already list: every one `@types/react` declares when
212	/// `full`, else the curated subset (`react_types::is_curated_html_attr`), each as React declares it minus what the layer
213	/// omits. Without React's types the curated table stands in, typed by name.
214	pub(super) fn layer_attributes(
215	    layer: &InheritedLayer,
216	    full: bool,
217	    has: impl Fn(&str) -> bool,
218	    ctx: &ResolutionContext,
219	    state: &mut ResolveState,
220	    depth: u8,
221	) -> Vec<Arc<ParsedProp>> {
222	    let Some(element) = layer.html_element.as_deref() else {
223	        return Vec::new();
224	    };
225	    let file = Utf8Path::new(&layer.file_name);
226	    // `ref` is a prop of `ComponentProps<"div">` and `HTMLProps<HTMLDivElement>` (`ClassAttributes`) but not of
227	    // `HTMLAttributes<HTMLDivElement>`.
228	    let bare = layer.type_name.strip_prefix("React.").unwrap_or(&layer.type_name);
229	    let takes_ref = matches!(bare, "ComponentProps" | "ComponentPropsWithRef" | "HTMLProps");
230	    let key = format!("{}\0{element}\0{full}", layer.file_name);
231	    note_augmentations(file, ctx);
232	    let cached = ctx.attribute_names.get(&key).map(|names| names.clone());
233	    let names: Arc<[String]> = match cached {
234	        Some(names) => names,
235	        None => {
236	            let declared = react_attribute_names(element, file, ctx);
237	            let names: Vec<String> = match (full, declared.is_empty()) {
238	                (true, false) => declared.into_iter().filter(|name| name != "key").collect(),
239	                (false, false) => declared
240	                    .into_iter()
241	                    .filter(|name| crate::react_types::is_curated_html_attr(element, name))
242	                    .collect(),
243	                (_, true) => Vec::new(),
244	            };
245	            let names: Arc<[String]> = names.into();
246	            ctx.attribute_names.insert(key, names.clone());
247	            names
248	        }
249	    };
250	    let loaded = !names.is_empty();
251	    if full && !loaded {
252	        state.diagnostics.push(
253	            Diagnostic::new(
254	                DiagnosticSeverity::Info,
255	                DiagnosticCode::MissingTypeLibrary,
256	                format!("@types/react could not be resolved, so the attributes of <{element}> are left out"),
257	            )
258	            .with_help("Check that @types/react is installed."),
259	        );
260	        return Vec::new();
261	    }
262	    let names: Vec<String> = if loaded {
263	        names.to_vec()
264	    } else {
265	        crate::react_types::notable_html_attrs(element)
266	            .iter()
267	            .chain(["ref"].iter())
268	            .map(|name| (*name).to_owned())
269	            .collect()
270	    };
271	    let parent = PropParent {
272	        name: format!("{}HTMLAttributes", capitalize_element(element)),
273	        file_name: "node_modules/@types/react/index.d.ts".to_owned(),
274	    };
275	    names
276	        .into_iter()
277	        .filter(|name| (takes_ref || name != "ref") && !has(name) && !layer.omitted.contains(name))
278	        .filter_map(|name| {
279	            if loaded {
280	                return super::alias::layer_attribute(layer, &name, ctx, state, depth).map(|prop| ctx.share(prop));
281	            }
282	            let prop_type = if name == "ref" {
283	                PropType::Named { name: "Ref".into(), args: vec![] }
284	            } else {
285	                infer_html_attr_prop_type(&name)
286	            };
287	            Some(ctx.share(ParsedProp::new(
288	                name,
289	                prop_type,
290	                false,
291	                None,
292	                String::new(),
293	                Default::default(),
294	                Some(parent.clone()),
295	                vec![],
296	            )))
297	        })
298	        .collect()
299	}
300	
301	/// The props of `React.AriaAttributes` or `React.RefAttributes<T>` (`bare`, applied to `args`), read from React's own
302	/// interface: `full` takes every one but `key`, else the curated subset. Empty without React's types, apart from the
303	/// `ref` a `RefAttributes` always has.
304	#[allow(clippy::too_many_arguments)]
305	pub(super) fn builtin_attributes(
306	    bare: &str,
307	    args: &[CollectedType],
308	    full: bool,
309	    file: &Utf8Path,
310	    ctx: &ResolutionContext,
311	    state: &mut ResolveState,
312	    depth: u8,
313	) -> Vec<Arc<ParsedProp>> {
314	    let react_file = super::react::resolve_react_types_file(file, ctx);
315	    let react_file = Utf8Path::new(&react_file);
316	    let root = CollectedType::Named { name: bare.into(), args: args.to_vec() };
317	    let key = format!("{react_file}\0{bare}");
318	    let cached = ctx.attribute_names.get(&key).map(|names| names.clone());
319	    let declared: Arc<[String]> = match cached {
320	        Some(names) => names,
321	        None => {
322	            let names: Arc<[String]> = attribute_names_from(root.clone(), react_file, ctx).into();
323	            ctx.attribute_names.insert(key, names.clone());
324	            names
325	        }
326	    };
327	    if declared.is_empty() {
328	        if bare == "RefAttributes" {
329	            let ref_type = PropType::Named { name: "Ref".into(), args: vec![] };
330	            let parent = PropParent { name: bare.to_owned(), file_name: react_file.to_string() };
331	            let prop = ParsedProp::new(
332	                "ref".into(),
333	                ref_type,
334	                false,
335	                None,
336	                String::new(),
337	                Default::default(),
338	                Some(parent),
339	                vec![],
340	            );
341	            return vec![ctx.share(prop)];
342	        }
343	        if full {
344	            state.diagnostics.push(
345	                Diagnostic::new(
346	                    DiagnosticSeverity::Info,
347	                    DiagnosticCode::MissingTypeLibrary,
348	                    format!("@types/react could not be resolved, so the attributes of {bare} are left out"),
349	                )
350	                .with_help("Check that @types/react is installed."),
351	            );
352	        }
353	        return Vec::new();
354	    }
355	    let arg_element = args.first().and_then(crate::react_types::html_element_from_collected);
356	    let element = arg_element.unwrap_or("div");
357	    // The reads are shared by every component that names the same interface for the same element.
358	    let shared = args.is_empty() || arg_element.is_some();
359	    declared
360	        .iter()
361	        .filter(|name| *name != "key" && (full || crate::react_types::is_curated_html_attr(element, name)))
362	        .filter_map(|name| {
363	            let read = |state: &mut ResolveState| attribute_from(root.clone(), name, react_file, ctx, state, depth);
364	            let prop = if shared {
365	                let memo_key = format!("{react_file}\0{bare}\0{}\0{name}", arg_element.unwrap_or(""));
366	                ctx.attribute_reads.get_or_resolve(&memo_key, depth, state, None, read)
367	            } else {
368	                read(state)
369	            };
370	            prop.map(|prop| ctx.share(prop))
371	        })
372	        .collect()
373	}
374	
375	pub(super) fn infer_html_attr_prop_type(attr_name: &str) -> PropType {
376	    match attr_name {
377	        "onClick" | "onKeyDown" | "onKeyUp" | "onFocus" | "onBlur" | "onChange" | "onInput" | "onSubmit"
378	        | "onReset" | "onLoad" | "onError" | "onPress" | "onPressStart" | "onPressEnd" | "onHoverStart"
379	        | "onHoverEnd" | "onFocusChange" | "onPressChange" => PropType::Function {
380	            type_params: vec![],
381	            params: vec![FunctionParam::new(Some("e".into()), PropType::Named { name: "Event".into(), args: vec![] })],
382	            return_type: Box::new(PropType::Void),
383	        },
384	        "disabled" | "readOnly" | "required" | "checked" | "multiple" | "noValidate" | "autoFocus" | "fullWidth"
385	        | "loading" | "isDisabled" | "isReadOnly" | "isRequired" => PropType::Boolean,
386	        "tabIndex" | "rows" | "cols" | "maxLength" | "min" | "max" | "width" | "height" | "size" => PropType::Number,
387	        "style" => PropType::CssProperties,
388	        "children" => PropType::ReactNode,
389	        _ => PropType::String,
390	    }
391	}
392	
393	pub(super) fn capitalize_element(element: &str) -> &'static str {
394	    match element {
395	        "button" => "Button",
396	        "input" => "Input",
397	        "a" => "Anchor",
398	        "textarea" => "Textarea",
399	        "select" => "Select",
400	        "form" => "Form",
401	        "label" => "Label",
402	        "img" => "Img",
403	        "video" => "Video",
404	        "audio" => "Audio",
405	        _ => "HTML",
406	    }
407	}
