//! HTML attribute inference helpers.

use std::collections::VecDeque;
use std::sync::Arc;

use camino::Utf8Path;

use crate::types::*;

use super::collected::resolve_collected_type;
use super::substitute::{build_substitution, substitute_alias, substitute_type};
use super::{ResolutionContext, ResolveState};

/// `JSX.IntrinsicElements[element]` in React's own types at `react_file`, when this run has them: Full mode merges them,
/// curated mode indexes them apart (`ResolutionContext::react_index`), and `none` mode and the dependency loader don't
/// read them.
pub(super) fn intrinsic_element<'a>(
    element: &str,
    react_file: &Utf8Path,
    ctx: &'a ResolutionContext,
) -> Option<&'a CollectedType> {
    let elements = ctx.react_index().lookup_interface_exact(react_file, "React.JSX.IntrinsicElements")?;
    Some(&elements.props.iter().find(|prop| prop.name == element)?.collected_type)
}

/// Record that this resolution reads React's augmentations: every file that declares into the `React` namespace, and
/// that the set of such files matters. Called wherever augmentations are read, and on the path that reuses a cached
/// attribute list, so every component that depends on them records it.
fn note_augmentations(react_file: &Utf8Path, ctx: &ResolutionContext) {
    use std::borrow::Borrow;
    let files = ctx.named_types.react_augmenting_files(react_file);
    super::deps::record_augmentations(files.into_iter().map(Borrow::<str>::borrow));
}

/// React's interface `key` (`React.HTMLAttributes`) followed by the augmentations other files merge into it
/// (`NamedTypeIndex::react_augmentations`): the project's and the loaded dependencies' in every mode, since curated mode
/// indexes only React's own file apart.
fn merged_interfaces<'a>(key: &str, react_file: &Utf8Path, ctx: &'a ResolutionContext) -> Vec<&'a CollectedInterface> {
    note_augmentations(react_file, ctx);
    let mut layers: Vec<&CollectedInterface> =
        ctx.react_index().lookup_interface_exact(react_file, key).into_iter().collect();
    layers.extend(ctx.named_types.react_augmentations(react_file, key));
    layers
}

/// The index holding `iface`: React's for its own interfaces, the project's and dependencies' for an augmentation.
fn index_of<'a>(
    iface: &CollectedInterface,
    react_file: &Utf8Path,
    ctx: &'a ResolutionContext,
) -> &'a crate::named_type_index::NamedTypeIndex {
    if iface.file_path == react_file { ctx.react_index() } else { &ctx.named_types }
}

/// The declaration of attribute `name` on intrinsic element `element`, read as TypeScript reads
/// `JSX.IntrinsicElements[element]` (`intrinsic_element`). `None` without React's types, or when the element has no such
/// attribute.
pub(super) fn react_attribute(
    element: &str,
    name: &str,
    react_file: &Utf8Path,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> Option<ParsedProp> {
    attribute_from(intrinsic_element(element, react_file, ctx)?.clone(), name, react_file, ctx, state, depth)
}

/// The declaration of attribute `name` among the members `root` (a type of React's) names, found through the interfaces
/// and aliases it extends and intersects.
fn attribute_from(
    root: CollectedType,
    name: &str,
    react_file: &Utf8Path,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> Option<ParsedProp> {
    // Declared inside `declare namespace React`, so keyed by their qualified names whichever way they are referenced.
    let key = |type_name: &str| format!("React.{}", type_name.strip_prefix("React.").unwrap_or(type_name));
    let mut pending = VecDeque::from([root]);
    // React's attribute types are a small tree; the bound only guards against a malformed declaration file.
    for _ in 0..64 {
        match pending.pop_front()? {
            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
            CollectedType::Intersection(members) => pending.extend(members),
            CollectedType::Named { name: type_name, args } => {
                let key = key(&type_name);
                // Defaulted parameters (`T = Element`) are not supplied, and need no warning.
                let mut ignored = Vec::new();
                let layers = merged_interfaces(&key, react_file, ctx);
                if !layers.is_empty() {
                    for iface in layers {
                        let params = index_of(iface, react_file, ctx).lookup_interface_type_params_for(iface);
                        let subst = params.map(|params| build_substitution(params, &args, react_file, &mut ignored));
                        let substituted =
                            |ty: &CollectedType| subst.as_ref().map_or_else(|| ty.clone(), |s| substitute_type(ty, s));
                        if let Some(raw) = iface.props.iter().find(|prop| prop.name == name) {
                            let ty = substituted(&raw.collected_type);
                            let prop_type = resolve_collected_type(&ty, &iface.file_path, ctx, state, depth);
                            let parent =
                                PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() };
                            return Some(ParsedProp::new(
                                name.to_owned(),
                                prop_type,
                                raw.required,
                                None,
                                raw.description.clone(),
                                raw.tags.clone(),
                                Some(parent.clone()),
                                vec![parent],
                            ));
                        }
                        pending.extend(iface.extends.iter().map(|extends| {
                            let (ExtendsRef::SameFile { name, type_args }
                            | ExtendsRef::Imported { local_name: name, type_args, .. }
                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
                            CollectedType::Named {
                                name: name.clone(),
                                args: type_args.iter().map(substituted).collect(),
                            }
                        }));
                    }
                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
                        Some(params) => {
                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut ignored))
                        }
                        None => alias.clone(),
                    };
                    match alias {
                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
                        // None of these names an attribute by itself; a new variant must say whether it does.
                        CollectedTypeAlias::Omit { .. }
                        | CollectedTypeAlias::Pick { .. }
                        | CollectedTypeAlias::Partial { .. }
                        | CollectedTypeAlias::Required { .. }
                        | CollectedTypeAlias::Union { .. }
                        | CollectedTypeAlias::LiteralUnion { .. } => {}
                    }
                }
            }
            _ => {}
        }
    }
    None
}

/// Every attribute name `JSX.IntrinsicElements[element]` declares in React's own types at `react_file`, in the order
/// `react_attribute` reads them; empty without those types.
fn react_attribute_names(element: &str, react_file: &Utf8Path, ctx: &ResolutionContext) -> Vec<String> {
    match intrinsic_element(element, react_file, ctx) {
        Some(root) => attribute_names_from(root.clone(), react_file, ctx),
        None => Vec::new(),
    }
}

/// Every attribute name `root` (a type of React's) carries, in the order `attribute_from` reads them.
fn attribute_names_from(root: CollectedType, react_file: &Utf8Path, ctx: &ResolutionContext) -> Vec<String> {
    let mut names: Vec<String> = Vec::new();
    let mut pending = VecDeque::from([root]);
    for _ in 0..64 {
        let Some(next) = pending.pop_front() else {
            break;
        };
        match next {
            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
            CollectedType::Intersection(members) => pending.extend(members),
            CollectedType::Named { name: type_name, args } => {
                let key = format!("React.{}", type_name.strip_prefix("React.").unwrap_or(&type_name));
                let layers = merged_interfaces(&key, react_file, ctx);
                if !layers.is_empty() {
                    for iface in layers {
                        names.extend(iface.props.iter().map(|prop| prop.name.clone()));
                        pending.extend(iface.extends.iter().map(|extends| {
                            let (ExtendsRef::SameFile { name, type_args }
                            | ExtendsRef::Imported { local_name: name, type_args, .. }
                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
                            CollectedType::Named { name: name.clone(), args: type_args.clone() }
                        }));
                    }
                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
                        Some(params) => {
                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut Vec::new()))
                        }
                        None => alias.clone(),
                    };
                    match alias {
                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
                        // None of these names an attribute by itself; a new variant must say whether it does.
                        CollectedTypeAlias::Omit { .. }
                        | CollectedTypeAlias::Pick { .. }
                        | CollectedTypeAlias::Partial { .. }
                        | CollectedTypeAlias::Required { .. }
                        | CollectedTypeAlias::Union { .. }
                        | CollectedTypeAlias::LiteralUnion { .. } => {}
                    }
                }
            }
            _ => {}
        }
    }
    let mut seen = rustc_hash::FxHashSet::default();
    names.retain(|name| seen.insert(name.clone()));
    names
}

/// The attributes of an HTML layer's element that `has` doesn't already list: every one `@types/react` declares when
/// `full`, else the curated subset (`react_types::is_curated_html_attr`), each as React declares it minus what the layer
/// omits. Without React's types the curated table stands in, typed by name.
pub(super) fn layer_attributes(
    layer: &InheritedLayer,
    full: bool,
    has: impl Fn(&str) -> bool,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> Vec<Arc<ParsedProp>> {
    let Some(element) = layer.html_element.as_deref() else {
        return Vec::new();
    };
    let file = Utf8Path::new(&layer.file_name);
    // `ref` is a prop of `ComponentProps<"div">` and `HTMLProps<HTMLDivElement>` (`ClassAttributes`) but not of
    // `HTMLAttributes<HTMLDivElement>`.
    let bare = layer.type_name.strip_prefix("React.").unwrap_or(&layer.type_name);
    let takes_ref = matches!(bare, "ComponentProps" | "ComponentPropsWithRef" | "HTMLProps");
    let key = format!("{}\0{element}\0{full}", layer.file_name);
    note_augmentations(file, ctx);
    let cached = ctx.attribute_names.get(&key).map(|names| names.clone());
    let names: Arc<[String]> = match cached {
        Some(names) => names,
        None => {
            let declared = react_attribute_names(element, file, ctx);
            let names: Vec<String> = match (full, declared.is_empty()) {
                (true, false) => declared.into_iter().filter(|name| name != "key").collect(),
                (false, false) => declared
                    .into_iter()
                    .filter(|name| crate::react_types::is_curated_html_attr(element, name))
                    .collect(),
                (_, true) => Vec::new(),
            };
            let names: Arc<[String]> = names.into();
            ctx.attribute_names.insert(key, names.clone());
            names
        }
    };
    let loaded = !names.is_empty();
    if full && !loaded {
        state.diagnostics.push(
            Diagnostic::new(
                DiagnosticSeverity::Info,
                DiagnosticCode::MissingTypeLibrary,
                format!("@types/react could not be resolved, so the attributes of <{element}> are left out"),
            )
            .with_help("Check that @types/react is installed."),
        );
        return Vec::new();
    }
    let names: Vec<String> = if loaded {
        names.to_vec()
    } else {
        crate::react_types::notable_html_attrs(element)
            .iter()
            .chain(["ref"].iter())
            .map(|name| (*name).to_owned())
            .collect()
    };
    let parent = PropParent {
        name: format!("{}HTMLAttributes", capitalize_element(element)),
        file_name: "node_modules/@types/react/index.d.ts".to_owned(),
    };
    names
        .into_iter()
        .filter(|name| (takes_ref || name != "ref") && !has(name) && !layer.omitted.contains(name))
        .filter_map(|name| {
            if loaded {
                return super::alias::layer_attribute(layer, &name, ctx, state, depth).map(|prop| ctx.share(prop));
            }
            let prop_type = if name == "ref" {
                PropType::Named { name: "Ref".into(), args: vec![] }
            } else {
                infer_html_attr_prop_type(&name)
            };
            Some(ctx.share(ParsedProp::new(
                name,
                prop_type,
                false,
                None,
                String::new(),
                Default::default(),
                Some(parent.clone()),
                vec![],
            )))
        })
        .collect()
}

/// The props of `React.AriaAttributes` or `React.RefAttributes<T>` (`bare`, applied to `args`), read from React's own
/// interface: `full` takes every one but `key`, else the curated subset. Empty without React's types, apart from the
/// `ref` a `RefAttributes` always has.
#[allow(clippy::too_many_arguments)]
pub(super) fn builtin_attributes(
    bare: &str,
    args: &[CollectedType],
    full: bool,
    file: &Utf8Path,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> Vec<Arc<ParsedProp>> {
    let react_file = super::react::resolve_react_types_file(file, ctx);
    let react_file = Utf8Path::new(&react_file);
    let root = CollectedType::Named { name: bare.into(), args: args.to_vec() };
    let key = format!("{react_file}\0{bare}");
    let cached = ctx.attribute_names.get(&key).map(|names| names.clone());
    let declared: Arc<[String]> = match cached {
        Some(names) => names,
        None => {
            let names: Arc<[String]> = attribute_names_from(root.clone(), react_file, ctx).into();
            ctx.attribute_names.insert(key, names.clone());
            names
        }
    };
    if declared.is_empty() {
        if bare == "RefAttributes" {
            let ref_type = PropType::Named { name: "Ref".into(), args: vec![] };
            let parent = PropParent { name: bare.to_owned(), file_name: react_file.to_string() };
            let prop = ParsedProp::new(
                "ref".into(),
                ref_type,
                false,
                None,
                String::new(),
                Default::default(),
                Some(parent),
                vec![],
            );
            return vec![ctx.share(prop)];
        }
        if full {
            state.diagnostics.push(
                Diagnostic::new(
                    DiagnosticSeverity::Info,
                    DiagnosticCode::MissingTypeLibrary,
                    format!("@types/react could not be resolved, so the attributes of {bare} are left out"),
                )
                .with_help("Check that @types/react is installed."),
            );
        }
        return Vec::new();
    }
    let arg_element = args.first().and_then(crate::react_types::html_element_from_collected);
    let element = arg_element.unwrap_or("div");
    // The reads are shared by every component that names the same interface for the same element.
    let shared = args.is_empty() || arg_element.is_some();
    declared
        .iter()
        .filter(|name| *name != "key" && (full || crate::react_types::is_curated_html_attr(element, name)))
        .filter_map(|name| {
            let read = |state: &mut ResolveState| attribute_from(root.clone(), name, react_file, ctx, state, depth);
            let prop = if shared {
                let memo_key = format!("{react_file}\0{bare}\0{}\0{name}", arg_element.unwrap_or(""));
                ctx.attribute_reads.get_or_resolve(&memo_key, depth, state, None, read)
            } else {
                read(state)
            };
            prop.map(|prop| ctx.share(prop))
        })
        .collect()
}

pub(super) fn infer_html_attr_prop_type(attr_name: &str) -> PropType {
    match attr_name {
        "onClick" | "onKeyDown" | "onKeyUp" | "onFocus" | "onBlur" | "onChange" | "onInput" | "onSubmit"
        | "onReset" | "onLoad" | "onError" | "onPress" | "onPressStart" | "onPressEnd" | "onHoverStart"
        | "onHoverEnd" | "onFocusChange" | "onPressChange" => PropType::Function {
            type_params: vec![],
            params: vec![FunctionParam::new(Some("e".into()), PropType::Named { name: "Event".into(), args: vec![] })],
            return_type: Box::new(PropType::Void),
        },
        "disabled" | "readOnly" | "required" | "checked" | "multiple" | "noValidate" | "autoFocus" | "fullWidth"
        | "loading" | "isDisabled" | "isReadOnly" | "isRequired" => PropType::Boolean,
        "tabIndex" | "rows" | "cols" | "maxLength" | "min" | "max" | "width" | "height" | "size" => PropType::Number,
        "style" => PropType::CssProperties,
        "children" => PropType::ReactNode,
        _ => PropType::String,
    }
}

pub(super) fn capitalize_element(element: &str) -> &'static str {
    match element {
        "button" => "Button",
        "input" => "Input",
        "a" => "Anchor",
        "textarea" => "Textarea",
        "select" => "Select",
        "form" => "Form",
        "label" => "Label",
        "img" => "Img",
        "video" => "Video",
        "audio" => "Audio",
        _ => "HTML",
    }
}

