67	        let react_from = match options.html_attributes {
68	            HtmlAttributeMode::Full => Some(from_dir.clone().unwrap_or_else(|| Utf8PathBuf::from("."))),
69	            HtmlAttributeMode::Curated => from_dir.clone(),
