103	/// A resolved component, the diagnostics its resolution produced, what that resolution depended on, and the relevance
104	/// evidence read with it.
105	pub(crate) struct Resolved {
106	    entry: ComponentEntry,
107	    diagnostics: ResolvedDiagnostics,
108	    depends_on: Dependencies,
109	    evidence: Option<Arc<crate::relevance::Inputs>>,
110	}
111	
112	impl Resolved {
113	    /// The entry as output, with the `used` lists relevance decides from its evidence and `sites`, the call sites of
114	    /// the revision it is published in. The one place an answer becomes output: a kept resolution is decided again
115	    /// against each revision's call sites, so an edit to a consumer reaches it without resolving it again.
116	    fn answer(&self, sites: &ProjectSites) -> ComponentEntry {
117	        let mut entry = self.entry.clone();
118	        decide(self.evidence.as_deref(), &mut entry, sites);
119	        entry
120	    }
121	
122	    /// [`Resolved::answer`] and the diagnostics, moved out when nothing else shares this resolution.
123	    fn into_parts(shared: Arc<Resolved>, sites: &ProjectSites) -> (ComponentEntry, ResolvedDiagnostics) {
124	        match Arc::try_unwrap(shared) {
125	            Ok(Resolved { mut entry, diagnostics, evidence, .. }) => {
126	                decide(evidence.as_deref(), &mut entry, sites);
127	                (entry, diagnostics)
128	            }
129	            Err(shared) => (shared.answer(sites), shared.diagnostics.clone()),
130	        }
131	    }
132	
133	    /// Whether this kept resolution answers differently against the call sites `after` than against `before`: an edit
134	    /// to a consumer re-decides its `used` lists without resolving it again. Decided by [`layers_differ`], the rule an
135	    /// eager revision reports a kept component by.
136	    fn redecided(&self, before: &ProjectSites, after: &ProjectSites) -> bool {
137	        let Some(inputs) = self.evidence.as_deref() else { return false };
138	        // The decision reads only the component's own call sites; the same sites decide the same lists.
139	        before.get(&inputs.site) != after.get(&inputs.site)
140	            && layers_differ(Some(&self.answer(before)), Some(&self.answer(after)))
141	    }
142	
143	    /// Whether this resolution can differ after `change`.
144	    fn affected_by(&self, change: &Change<'_>) -> bool {
145	        self.depends_on.files.contains(change.file.as_str())
146	            || (change.created && self.depends_on.resolves_modules)
147	            || (change.react_namespace && self.depends_on.reads_augmentations)
148	            || change.bare_names.iter().any(|name| self.depends_on.bare_names.contains(name.as_str()))
149	    }
