152	/// Whether `before` and `after` publish different layers or list different props. Relevance writes the layers'
153	/// `used` lists and moves props between the listing and the layers, so this is how a kept resolution's answer can move
154	/// between revisions: the one rule both kinds of revision report it by. The listing is compared too, since a prop can
155	/// leave it for a layer that already holds its name, which leaves the layers unchanged.
156	fn layers_differ(before: Option<&ComponentEntry>, after: Option<&ComponentEntry>) -> bool {
157	    let published = |entry: &ComponentEntry| {
158	        (
159	            entry.inheritance.clone(),
160	            entry.props.keys().cloned().collect::<Vec<_>>(),
161	            entry.notable_inherited.keys().cloned().collect::<Vec<_>>(),
162	        )
163	    };
164	    before.map(published) != after.map(published)
165	}
