167	/// Writes the `used` lists relevance decides for `entry` from its `evidence` and the revision's `sites`; without
168	/// evidence (a panic gathering it), none.
169	fn decide(evidence: Option<&crate::relevance::Inputs>, entry: &mut ComponentEntry, sites: &ProjectSites) {
170	    if let Some(inputs) = evidence {
171	        let call_sites = sites.get(&inputs.site).unwrap_or(&crate::relevance::NO_CALL_SITES);
