90	            Some((Declaration::Alias(alias), declared)) => match &**alias {
91	                CollectedTypeAlias::Pick { keys, .. } => read.pick_keys(keys, &declared, &lookup),
92	                // A union's arms are each the props type (a discriminated union's fields are its own).
93	                CollectedTypeAlias::Intersection { members, .. } | CollectedTypeAlias::Union { members, .. } => {
94	                    members.iter().for_each(|member| read.part(member, &declared, &lookup));
95	                }
96	                CollectedTypeAlias::Passthrough { target: part, .. }
97	                | CollectedTypeAlias::Partial { base: part, .. }
98	                | CollectedTypeAlias::Required { base: part, .. } => read.part(part, &declared, &lookup),
99	                // `Omit<Base, Keys>` as the props type: read as the same `Omit` written in place, so only a `Pick` in
100	                // its base selects keys; its members are not inherited, as an omitted one does not reach.
101	                CollectedTypeAlias::Omit { base, keys, .. } => {
102	                    read.picks("Omit", &[base.clone(), keys.clone()], &declared, &lookup, 0);
103	                }
104	                CollectedTypeAlias::LiteralUnion { .. } => {}
105	            },
106	            None => {}
107	        }
108	        read
109	    }
110	
111	    /// The members `interface`'s bases declare outside the ambient declarations, through their own bases, each base
112	    /// found from the file that names it; and the keys a `Pick` among them names.
113	    fn bases<'a>(&mut self, interface: &CollectedInterface, lookup: &impl Lookup<'a>, depth: u8) {
114	        for base in &interface.extends {
115	            let (ExtendsRef::SameFile { name, type_args } | ExtendsRef::Imported { local_name: name, type_args, .. }) =
116	                base
117	            else {
118	                continue;
119	            };
120	            self.pick(name, type_args, &interface.file_path, lookup);
121	            self.inherit(name, &interface.file_path, lookup, depth);
122	        }
123	    }
124	
125	    /// The members the interface `name` written in `from` declares and inherits, unless it is ambient.
126	    fn inherit<'a>(&mut self, name: &str, from: &Utf8Path, lookup: &impl Lookup<'a>, depth: u8) {
127	        if depth >= MAX_ALIAS_DEPTH {
128	            return;
129	        }
130	        if let Some((Declaration::Interface(base), declared)) = lookup(name, &[], from)
131	            && !crate::origin::is_ambient_declaration(declared.as_str(), Some(&base.tags))
132	        {
133	            self.inherited.extend(base.props.iter().map(|prop| prop.name.clone()));
134	            self.bases(base, lookup, depth + 1);
135	        }
136	    }
137	
138	    /// One part of the props type written in `from`: a type literal's fields are its own, an intersection's parts are
139	    /// parts, a `Pick` names its keys; any other name is a base.
140	    fn part<'a>(&mut self, part: &CollectedType, from: &Utf8Path, lookup: &impl Lookup<'a>) {
141	        match part {
142	            CollectedType::Object(fields) | CollectedType::Callable { fields, .. } => {
143	                self.own.extend(fields.iter().map(|field| field.name.clone()));
144	            }
145	            CollectedType::Intersection(parts) | CollectedType::Union(parts) => {
146	                parts.iter().for_each(|part| self.part(part, from, lookup));
147	            }
148	            CollectedType::AtFile { file, inner } => self.part(inner, file, lookup),
149	            CollectedType::Named { name, args } => {
150	                self.pick(name, args, from, lookup);
151	                self.inherit(name, from, lookup, 0);
152	            }
153	            _ => {}
154	        }
155	    }
156	
157	    /// The keys of `name<args>` written in `from` when it is `Pick<Base, Keys>`, or a `Pick` under a utility that keeps
158	    /// the keys it names (`Omit`, `Partial`, `Required`, `Readonly`: an omitted key no longer reaches the component, so
159	    /// naming it changes nothing), or a type alias whose body is one of these. Any other form names no key.
160	    fn pick<'a>(&mut self, name: &str, args: &[CollectedType], from: &Utf8Path, lookup: &impl Lookup<'a>) {
161	        self.picks(name, args, from, lookup, 0);
162	    }
163	
164	    fn picks<'a>(&mut self, name: &str, args: &[CollectedType], from: &Utf8Path, lookup: &impl Lookup<'a>, depth: u8) {
165	        if depth >= MAX_ALIAS_DEPTH {
166	            return;
167	        }
168	        match (name, args) {
169	            ("Pick", [_, keys]) => self.pick_keys(keys, from, lookup),
170	            ("Omit", [base, keys]) => {
171	                // The omitted keys are not picked; only whether they are a closed set of literals is kept.
172	                let mut omitted = Self::default();
173	                omitted.keys(keys, from, lookup, 0);
174	                self.declined |= omitted.declined;
175	                let (base, at) = written_at(base, from);
176	                if let CollectedType::Named { name, args } = base {
177	                    self.picks(name, args, &at, lookup, depth + 1);
178	                }
179	            }
180	            ("Partial" | "Required" | "Readonly", [base, ..]) => {
181	                let (base, at) = written_at(base, from);
182	                if let CollectedType::Named { name, args } = base {
183	                    self.picks(name, args, &at, lookup, depth + 1);
184	                }
185	            }
186	            // An alias, generic or not: its instantiation with `args` is what the props type selects.
187	            (_, args) => {
188	                let Some((Declaration::Alias(alias), declared)) = lookup(name, args, from) else { return };
189	                let base = match &**alias {
190	                    CollectedTypeAlias::Pick { keys, .. } => {
191	                        self.pick_keys(keys, &declared, lookup);
192	                        return;
193	                    }
194	                    CollectedTypeAlias::Omit { base, keys, .. } => {
195	                        // As an `Omit` written in place: its keys decide only whether it is declined.
196	                        let mut omitted = Self::default();
197	                        omitted.keys(keys, &declared, lookup, 0);
198	                        self.declined |= omitted.declined;
199	                        base
200	                    }
201	                    CollectedTypeAlias::Partial { base, .. }
202	                    | CollectedTypeAlias::Required { base, .. }
203	                    | CollectedTypeAlias::Passthrough { target: base, .. } => base,
204	                    CollectedTypeAlias::LiteralUnion { .. }
205	                    | CollectedTypeAlias::Union { .. }
206	                    | CollectedTypeAlias::Intersection { .. } => return,
207	                };
208	                // An argument an instantiation substituted is read where it was written (`AtFile`).
209	                let (base, at) = written_at(base, &declared);
210	                if let CollectedType::Named { name, args } = base {
211	                    self.picks(name, args, &at, lookup, depth + 1);
212	                }
213	            }
214	        }
215	    }
216	
217	    /// The keys a `Pick` selects ([`Self::keys`]); a key set not proven marks the props type's selection unproven.
218	    fn pick_keys<'a>(&mut self, keys: &CollectedType, from: &Utf8Path, lookup: &impl Lookup<'a>) {
219	        let mut picked = Self::default();
220	        picked.keys(keys, from, lookup, 0);
221	        self.picked.extend(picked.picked);
222	        self.declined |= picked.declined;
223	        self.unproven_pick |= picked.declined;
224	    }
225	
226	    /// The string literal keys `keys` written in `from` names, through unions and aliases, each alias found from the
227	    /// file that names it.
228	    fn keys<'a>(&mut self, keys: &CollectedType, from: &Utf8Path, lookup: &impl Lookup<'a>, depth: u8) {
229	        match keys {
230	            CollectedType::StringLiteral(key) => {
231	                self.picked.insert(key.to_string());
232	            }
233	            // A key set an instantiation substituted, read where it was written.
234	            CollectedType::AtFile { file, inner } => self.keys(inner, file, lookup, depth),
235	            CollectedType::Union(keys) => keys.iter().for_each(|key| self.keys(key, from, lookup, depth)),
236	            CollectedType::Named { name, args } if depth < MAX_ALIAS_DEPTH => {
237	                let Some((Declaration::Alias(alias), declared)) = lookup(name, args, from) else {
238	                    self.declined = true;
239	                    return;
240	                };
241	                match &**alias {
242	                    CollectedTypeAlias::LiteralUnion { members, .. } => self.picked.extend(members.iter().cloned()),
243	                    CollectedTypeAlias::Passthrough { target, .. } => self.keys(target, &declared, lookup, depth + 1),
244	                    CollectedTypeAlias::Union { members, .. } => {
245	                        members.iter().for_each(|key| self.keys(key, &declared, lookup, depth + 1));
246	                    }
247	                    CollectedTypeAlias::Pick { .. }
248	                    | CollectedTypeAlias::Omit { .. }
249	                    | CollectedTypeAlias::Intersection { .. }
250	                    | CollectedTypeAlias::Partial { .. }
251	                    | CollectedTypeAlias::Required { .. } => self.declined = true,
252	                }
253	            }
254	            // Any other key form (`string`, `string & {}`, a template literal, `keyof X`, an alias past the depth)
255	            // is not a closed set of literals.
256	            _ => self.declined = true,
257	        }
258	    }
259	
260	    /// Whether `parent` is the interface the props type is.
261	    fn declares(&self, parent: &PropParent) -> bool {
262	        self.interface.as_ref().is_some_and(|(name, file)| *name == parent.name && *file == parent.file_name)
263	    }
264	}
