266	/// `ty` and the file it is written in: an `AtFile` (an argument substituted into a declaration of another file) names
267	/// its own file.
268	fn written_at<'t>(ty: &'t CollectedType, from: &Utf8Path) -> (&'t CollectedType, Utf8PathBuf) {
269	    match ty {
270	        CollectedType::AtFile { file, inner } => written_at(inner, file),
271	        _ => (ty, from.to_owned()),
272	    }
273	}
