275	/// The props-type evidence of every member a lane's answer reaches: each prop it lists (`rows`, with its
276	/// `notableInherited` ones) in order, then each member of its collapsed `layers` it does not list. A member is ambient
277	/// when every declaration of it is: React's own, or one of the `private` sources its library marks private (ADR 0028:
278	/// by provenance, never by name); a member with no declaration is not.
279	/// `large` says whether the member is one of a generated set: a member of a layer (a source the resolver collapsed past
280	/// its thresholds), a member a mapped type copies from a large interface's keys
281	/// ([`ParsedProp::copied_from_large_keys`]), or a member of a source (its `parent`) that has a layer or reaches with
282	/// more than [`LARGE_API_SOURCE`] listed props. A listed prop with no `parent` has no known source and is large only when copied.
283	///
284	/// A member is own when the props type writes it, and overrides when, besides, a base declares it: its `parent` or a
285	/// declaration is not the props type, or a collapsed layer holds it.
286	pub(crate) fn members<'a>(
287	    props_type: &PropsType,
288	    rows: impl IntoIterator<Item = &'a ParsedProp>,
289	    layers: &[InheritedLayer],
290	    private: &BTreeMap<String, BTreeSet<String>>,
291	) -> Vec<Member> {
292	    let ambient = |type_name: &str, file: &str| {
293	        crate::origin::declaration_origin(file).is_ambient()
294	            || private.get(file).is_some_and(|names| names.contains(type_name))
295	    };
296	    let layered: BTreeSet<&str> = layers.iter().flat_map(|layer| layer.members.iter().map(String::as_str)).collect();
297	    let mut listed = BTreeSet::new();
298	    let rows: Vec<&ParsedProp> = rows.into_iter().filter(|prop| listed.insert(prop.name.as_str())).collect();
299	    // Each source's reach over the listed props.
300	    let mut reach: BTreeMap<(&str, &str), usize> = BTreeMap::new();
301	    for parent in rows.iter().filter_map(|prop| prop.parent.as_ref()) {
302	        *reach.entry((&parent.name, &parent.file_name)).or_default() += 1;
303	    }
304	    // A listed prop of a source the resolver collapsed (a notable member of its layer) is of that generated set too.
305	    for layer in layers {
306	        reach.insert((&layer.type_name, &layer.file_name), usize::MAX);
307	    }
308	    // A project source's size is the resolver's to judge: it collapses one past its threshold into a layer, whose
309	    // members not listed are generated below. A listed prop of the project's own (the props type itself, of any size)
310	    // is generated only when a mapped type copies it from a large key set.
311	    let large = |parent: &PropParent| {
312	        crate::origin::declaration_origin(&parent.file_name) != crate::origin::Origin::Project
313	            && reach
314	                .get(&(parent.name.as_str(), parent.file_name.as_str()))
315	                .is_some_and(|reaching| *reaching > LARGE_API_SOURCE)
316	    };
317	    let mut members = Vec::new();
318	    for prop in rows {
319	        let own = props_type.own.contains(&prop.name) || prop.parent.as_ref().is_some_and(|p| props_type.declares(p));
320	        let based = layered.contains(prop.name.as_str())
321	            || prop.parent.iter().chain(&prop.declarations).any(|parent| !props_type.declares(parent));
322	        let given = member(props_type, &prop.name);
323	        members.push(Member {
324	            own,
325	            overrides: own && based,
326	            required: prop.required,
327	            default_tag: given.default_tag || prop.default_value.is_some() || prop.tags.contains_key("default"),
328	            documented: !prop.description.is_empty(),
329	            literal_union: is_literal_union(&prop.prop_type),
330	            // Ambient only when every declaration is: a member a library's API declares too (React Aria's `onFocus`
331	            // in `FocusEvents`, beside React's `DOMAttributes`) is API. With no declaration it is unknown: not ambient.
332	            // The checker states `parent` only for an interface; a declaration in a type literal is still in a file.
333	            ambient: (prop.parent.is_some() || !prop.declarations.is_empty())
334	                && prop.parent.iter().chain(&prop.declarations).all(|parent| ambient(&parent.name, &parent.file_name)),
335	            large: prop.copied_from_large_keys || prop.parent.as_ref().is_some_and(large),
336	            ..given
337	        });
338	    }
339	    for layer in layers {
340	        let layer_ambient = ambient(&layer.type_name, &layer.file_name);
341	        for name in layer.members.iter().filter(|name| !listed.contains(name.as_str())) {
342	            let own = props_type.own.contains(name);
343	            members.push(Member {
344	                own,
345	                overrides: own,
346	                ambient: layer_ambient,
347	                large: true,
348	                ..member(props_type, name)
349	            });
350	        }
351	    }
352	    members
353	}
354	
355	/// The evidence the props type gives `name` whatever the lane says: picked, defaulted by the signature.
356	fn member(props_type: &PropsType, name: &str) -> Member {
357	    Member {
358	        name: name.to_owned(),
359	        picked: props_type.picked.contains(name),
360	        default_tag: props_type.defaulted.contains(name),
361	        ..Member::default()
362	    }
363	}
364	
365	/// Whether `prop_type` is a union of literals or enum members (`null` and `undefined` beside them allowed), or a
366	/// variant union.
367	fn is_literal_union(prop_type: &PropType) -> bool {
368	    let members = match prop_type {
369	        PropType::LiteralUnion { .. } => return true,
370	        PropType::Union(members) => members,
371	        _ => return false,
372	    };
373	    let literal = |member: &PropType| {
374	        matches!(
375	            member,
376	            PropType::StringLiteral(_)
377	                | PropType::NumberLiteral(_)
378	                | PropType::BoolLiteral(_)
379	                | PropType::BigIntLiteral(_)
380	                | PropType::EnumMember { .. }
381	        )
382	    };
383	    members.iter().any(literal)
384	        && members.iter().all(|member| literal(member) || matches!(member, PropType::Null | PropType::Undefined))
385	}
