539	        let dir = tempfile::Builder::new().prefix("PropsTypeModel").tempdir().unwrap();
540	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
541	        let path = root.join("Components.tsx");
542	        let text = format!("{}{COMPONENTS}", big());
543	        std::fs::write(&path, &text).unwrap();
544	        let options = PipelineOptions {
545	            src_dirs: vec![root.clone()],
546	            cache_dir: Some(root.join(".cache")),
547	            html_attributes: HtmlAttributeMode::None,
548	            collapse_inherited_props: CollapseInheritedProps::All,
549	            ..PipelineOptions::default()
550	        };
551	        let output = extract(&options);
552	        props_types(&path, &text)
553	            .into_iter()
554	            .map(|(name, read)| {
555	                let structural = output.components[&name].clone();
556	                let mut checker = structural.clone();
557	                for prop in checker.props.values_mut() {
558	                    let Some(layer) = structural.inheritance.iter().find(|layer| layer.members.contains(&prop.name))
559	                    else {
560	                        continue;
561	                    };
562	                    if prop.parent.is_none() {
563	                        let base = PropParent { name: layer.type_name.clone(), file_name: layer.file_name.clone() };
564	                        *prop = std::sync::Arc::new(ParsedProp::new(
565	                            prop.name.clone(),
566	                            prop.prop_type.clone(),
567	                            prop.required,
568	                            prop.default_value.clone(),
569	                            prop.description.clone(),
570	                            prop.tags.clone(),
571	                            Some(base.clone()),
572	                            vec![base],
573	                        ));
574	                    }
575	                }
576	                (name, read, structural, checker)
577	            })
578	            .collect()
579	    }
580	
581	    fn evidence(read: &PropsType, entry: &ComponentEntry) -> Vec<Member> {
582	        let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
583	        members(read, rows, &entry.inheritance, &BTreeMap::new())
584	    }
585	
586	    #[test]
587	    fn both_lanes_give_the_same_evidence_for_pick_omit_override_and_required() {
588	        for (name, read, structural, checker) in lanes() {
589	            let (from_structural, from_checker) = (evidence(&read, &structural), evidence(&read, &checker));
590	            assert_eq!(from_structural, from_checker, "{name}");
591	            let shown = decided(from_structural);
592	            let row = |prop: &str| shown.rows.iter().any(|row| row == prop);
593	            match name.as_str() {
594	                "ByExtends" | "ByIntersection" => {
595	                    assert!(row("size") && !row("tone") && !row("p0"), "{name}: {shown:?}")
596	                }
597	                "ByPick" => assert_eq!(shown.rows, ["own", "p1", "p2"], "{name}"),
598	                "ByOmit" => {
599	                    assert!(row("own") && row("p5") && !row("p1") && !row("p0"), "{name}: {shown:?}");
600	                    assert!(!shown.collapsed.iter().any(|member| member == "p1"), "{name}: {shown:?}");
601	                }
602	                // `Small` is an API source: all of it is listed.
603	                "ByRequired" => assert_eq!(
604	                    (shown.rows, shown.collapsed),
605	                    (vec!["maybe".to_owned(), "need".to_owned(), "own".to_owned()], vec![])
606	                ),
607	                _ => {}
608	            }
609	        }
610	    }
611	
612	    #[test]
613	    fn a_doc_comment_or_literal_union_is_reported_but_promotes_nothing_alone() {
614	        let union = PropType::Union(vec![PropType::StringLiteral("a".into()), PropType::Undefined]);
615	        let documented = ParsedProp::new(
616	            "tone".into(),
617	            union,
618	            false,
619	            None,
620	            "The tone.".into(),
621	            Default::default(),
622	            Some(PropParent { name: "Base".into(), file_name: "/base.ts".into() }),
623	            Vec::new(),
624	        );
625	        let members = members(&PropsType::default(), [&documented], &[], &BTreeMap::new());
626	        assert!(members[0].documented && members[0].literal_union && !members[0].own, "{members:?}");
627	        // `Base` declares one member: an API source, listed whatever the evidence.
628	        assert!(!members[0].large, "{members:?}");
629	        assert_eq!(decided(members.clone()).rows, ["tone"]);
630	        assert_eq!(decided(vec![Member { large: true, ..members[0].clone() }]).collapsed, ["tone"]);
631	        assert!(!is_literal_union(&PropType::Union(vec![PropType::String, PropType::StringLiteral("a".into())])));
632	        // A declaration in a type literal has no `parent` in the checker lane; its file still says ambient.
633	        let react = PropParent { name: "__type".into(), file_name: "/node_modules/@types/react/index.d.ts".into() };
634	        let handler = ParsedProp::new(
635	            "onClick".into(),
636	            PropType::Any,
637	            false,
638	            None,
639	            String::new(),
640	            Default::default(),
641	            None,
642	            vec![react],
643	        );
644	        assert!(super::members(&PropsType::default(), [&handler], &[], &BTreeMap::new())[0].ambient);
645	    }
646	
647	    /// Two files: the component's, and one declaring its props type and what that type names.
648	    fn across_files(component: &str, declarations: &str) -> PropsType {
649	        let (here, there) = (Utf8Path::new("/fixtures/Button.tsx"), Utf8Path::new("/fixtures/props.ts"));
650	        let (component, declarations) = (parse_file(here, component), parse_file(there, declarations));
651	        // Only the props type is imported; every other name is found in the file that writes it.
652	        let lookup = |name: &str, _: &[CollectedType], from: &Utf8Path| {
653	            let (data, path) = match (from == here, name) {
654	                (true, "Props") => (&declarations, there),
655	                (true, _) => (&component, here),
656	                (false, _) => (&declarations, there),
657	            };
658	            lookup(data, path, name)
659	        };
660	        PropsType::read(&component.component_mappings[0], lookup)
661	    }
662	
663	    #[test]
664	    fn a_pick_of_an_imported_props_type_finds_its_keys_where_the_props_type_is_declared() {
665	        let read = across_files(
666	            "import type { Props } from './props';\nexport function Button(props: Props) { return null; }\n",
667	            "interface Base { a?: string; b?: string; c?: string }\ntype Keys = 'a' | 'b';\n\
668	             export type Props = Pick<Base, Keys>;\n",
669	        );
670	        assert_eq!(read.picked, BTreeSet::from(["a".to_owned(), "b".to_owned()]));
671	    }
672	
673	    #[test]
674	    fn a_forwarding_target_that_only_extends_a_base_reaches_the_bases_members() {
675	        let read = across_files(
676	            "import type { Props } from './props';\nexport function Inner(props: Props) { return null; }\n",
677	            "interface Base { tone?: string; size?: string }\nexport interface Props extends Base {}\n",
678	        );
679	        let names: Vec<String> = read.reachable_members().into_iter().map(|member| member.name).collect();
680	        assert_eq!(names, ["size", "tone"]);
681	    }
