import json, sys

def load(path):
    with open(path) as f:
        data = json.load(f)
    data.pop("stats", None)
    return data

a, b = load(sys.argv[1]), load(sys.argv[2])
if a == b and json.dumps(a) == json.dumps(b):
    print("same", sys.argv[1])
    sys.exit(0)
print("DIFF", sys.argv[1])
for key in a:
    if a.get(key) != b.get(key):
        print(" key differs:", key)
        if key == "components":
            for name in a[key]:
                if a[key][name] != b[key].get(name):
                    print("  component", name)
                    print("   new:", json.dumps(a[key][name])[:1500])
                    print("   base:", json.dumps(b[key].get(name))[:1500])
                    break
sys.exit(1)

