import bisect, collections, gzip, json, re, sys

# usage: agg.py <profile.json.gz>... ; inclusive sample counts per function (inlined frames included)
incl = collections.Counter()
total = 0
for path in sys.argv[1:]:
    d = json.load(gzip.open(path))
    syms = json.load(open(path.replace(".json.gz", ".json.syms.json")))
    strings = syms["string_table"]
    tables = {}
    for lib in syms["data"]:
        entries = sorted(lib["symbol_table"], key=lambda e: e["rva"])
        tables[lib["debug_name"]] = ([e["rva"] for e in entries], entries)
    libs = d["libs"]
    for t in d["threads"]:
        ft, st, rt, fn = t["frameTable"], t["stackTable"], t["resourceTable"], t["funcTable"]
        cache = {}

        def names(frame):
            if frame in cache:
                return cache[frame]
            func = ft["func"][frame]
            res = fn["resource"][func]
            out = []
            if res is not None and res >= 0:
                lib = libs[rt["lib"][res]]["debugName"]
                if lib in tables:
                    rvas, entries = tables[lib]
                    i = bisect.bisect_right(rvas, ft["address"][frame]) - 1
                    if i >= 0 and ft["address"][frame] < rvas[i] + entries[i]["size"]:
                        e = entries[i]
                        out = [strings[f["function"]] for f in e.get("frames", [])] or [strings[e["symbol"]]]
                        out.append(strings[e["symbol"]])
            cache[frame] = out
            return out

        for s, w in zip(t["samples"]["stack"], t["samples"]["weight"] or [1] * len(t["samples"]["stack"])):
            if s is None:
                continue
            seen = set()
            while s is not None:
                for n in names(st["frame"][s]):
                    n = re.sub(r"::h[0-9a-f]{16}$", "", n)
                    seen.add(n)
                s = st["prefix"][s]
            total += w
            for n in seen:
                incl[n] += w
print("total samples", total)
pat = re.compile(sys.argv[0] and r"caliper_docgen|relevance|resolver|serde|alloc::|drop_in_place|memo")
for n, c in incl.most_common(400):
    if pat.search(n):
        print(c, n[:170])

